CREATE VIEW [FO].[vwProduct]
AS 
SELECT 
	T1.[ITEMTYPE] AS [PRODUCTTYPE],
	T1.[ITEMID] AS [PRODUCTNUMBER],
	T1.RECID AS [RECID], 
	T2.[SEARCHNAME] AS [PRODUCTSEARCHNAME],
	T1.[ITEMID] AS [ITEMNUMBER],
	T1.[NAMEALIAS] AS [SEARCHNAME],
	PT.[NAME] AS 'Product_Name',
	T3.[ITEMGROUPID] AS [PRODUCTGROUPID],
	T1.[TAXRATETYPE],
	CASE WHEN T1.[ITEMID] LIKE 'CON%' THEN 1 ELSE 0 END AS 'Is Concession',
	CASE WHEN T1.[ITEMID] IN ('CONPWRQ2','CONPWRQ3','CONRETIREDSPECIAL','CONPWRQ1','CONRETIREDFL','CONRETIRED') THEN 'Retired' 
		  WHEN T1.[ITEMID] LIKE 'CON%' THEN 'Non-Retired'
		  ELSE 'N/A' END AS 'Retired Concession Flag',
	CASE 
		WHEN T1.[ITEMID] IN ('PROASSOCCAND', 'PROAPCCAND') THEN 'Candidate'
		WHEN T1.[ITEMID] IN ('PROFRICS', 'PROASSOC', 'PROMRICS', 'PROMRICSU2', 'PROREDAM') THEN 'Qualified'
		WHEN T1.[ITEMID] = 'S1X' THEN 'S1X'
		WHEN T1.[ITEMID] IN ('RAFEE_APCC','RAFEE_ACAND','RAFEE_ASSOC','RAFEE_FRICS','RAFEE_MRICS','RAFEE_PMU2') THEN 'Readmission'
		WHEN T1.[ITEMID] IN ('CORPSUB','APCENVSUB','AFODEF','AFODE','APCHISTSUB','LPFEE_APCC') THEN 'Other'
		WHEN T1.[ITEMID] LIKE 'CON%' THEN 'Concession'
		ELSE 'Unknown' END AS 'Product Category',
	T1.[DATAAREAID],
	T1.[PARTITION],
	T1.[DataLakeModified_DateTime],
	T1.[CREATEDBY],
	T1.[CREATEDDATETIME],
	T1.[MODIFIEDBY],
	T1.[MODIFIEDDATETIME],
	T1.[ITEMID] + '_' + T1.[DATAAREAID] AS [Product_Key]
FROM [synapse_fo].[INVENTTABLE] T1
	CROSS JOIN [synapse_fo].[ECORESPRODUCT] T2
	LEFT JOIN [synapse_fo].[ECORESPRODUCTTRANSLATION] PT
		ON PT.PRODUCT = T1.PRODUCT
	LEFT OUTER JOIN [synapse_fo].[INVENTITEMGROUPITEM] T3 ON (
			(
				(T1.DATAAREAID = T3.ITEMDATAAREAID)
				AND (T1.PARTITION = T3.PARTITION)
				)
			AND (
				(T1.ITEMID = T3.ITEMID)
				AND (T1.PARTITION = T3.PARTITION)
				)
			)

WHERE (
		(T1.PRODUCT = T2.RECID)
		AND (T1.PARTITION = T2.PARTITION)
		AND T1.[DATAAREAID] = 'rcs'
		)
